package MathEx;

public class MathEx {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println(Math.round(4.4));
		System.out.println(Math.round(4.8));
		
		System.out.println(Math.ceil(4.4));
		System.out.println(Math.ceil(4.8));
		
		System.out.println(Math.floor(4.4));
		System.out.println(Math.floor(4.8));
		
		System.out.println(Math.max(10,15));
		System.out.println(Math.min(10,15));
		
		System.out.println(Math.sqrt(64));
		
		System.out.println(Math.abs(-5.7));
		
		System.out.println(Math.pow(2,4));
		
		System.out.println(Math.random());
		
	
	}

}
